"use server";

/**
 * Posts a comment and fans out mention notifications; rate limited.
 *
 * Owner D. The notification fan-out itself is not triggered here — the service
 * emits `comment.created` and `NotificationService` subscribes to it. This
 * action only validates, authorizes, charges the rate limit and revalidates.
 *
 * Must call (do not reimplement): createCommentSchema, can, consumeRateLimit,
 * getActor, toActionResult
 */

import { ForbiddenActionError, RateLimitedError } from "@/actions/_lib/action-errors";
import { PENDING_COMMENT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { createCommentSchema, type CreateCommentInput } from "@/schemas/comment";
import { createComment } from "@/server/services/comment-service";
import type { ActionResult } from "@/types/api";
import type { Comment } from "@/types/comment";

const COMMENT_BUCKET = "comment:create";

const run = withAction<typeof createCommentSchema, Comment>(
  createCommentSchema,
  async (raw, actor) => {
    const input = raw as CreateCommentInput;

    const allowed = can(actor, "comment:create", {
      kind: "comment",
      orgId: input.orgId,
      commentId: PENDING_COMMENT_ID,
      authorId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("comment:create");
    }

    const verdict = await consumeRateLimit(input.orgId, COMMENT_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(COMMENT_BUCKET, verdict.resetAt);
    }

    const comment = await createComment(actor, input);
    revalidateTagged([issueTag(input.issueId)], CACHE_PROFILES.seconds);
    return comment;
  },
  { revalidate: ["comments"], cacheProfile: "seconds" },
);

export async function createCommentAction(raw: unknown): Promise<ActionResult<Comment>> {
  return run(raw);
}

/**
 * Per-user, per-kind delivery matrix consulted before every fan-out.
 */
import { and, eq } from "drizzle-orm";
import { getDb, notificationPreferences } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, toPreference } from "./_mappers";
import type { UpdateNotificationPreferenceInput } from "@/schemas/notification";
import type { OrgId, UserId } from "@/types/common";
import type {
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export async function listPreferences(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly NotificationPreference[]> {
  const rows = getDb()
    .select()
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.userId, userId),
      ),
    )
    .all();
  return rows.map(toPreference);
}

/**
 * `null` means "no explicit row" — the fan-out then falls back to the default
 * channel set rather than treating the absence as "everything off".
 */
export async function getPreference(
  orgId: OrgId,
  userId: UserId,
  kind: NotificationKind,
): Promise<NotificationPreference | null> {
  const row = getDb()
    .select()
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.userId, userId),
        eq(notificationPreferences.kind, kind),
      ),
    )
    .get();
  return row ? toPreference(row) : null;
}

export async function upsertPreference(
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  const row = getDb()
    .insert(notificationPreferences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      kind: input.kind,
      inApp: input.inApp,
      email: input.email,
      digestOnly: input.digestOnly,
    })
    .onConflictDoUpdate({
      target: [
        notificationPreferences.orgId,
        notificationPreferences.userId,
        notificationPreferences.kind,
      ],
      set: {
        inApp: input.inApp,
        email: input.email,
        digestOnly: input.digestOnly,
      },
    })
    .returning()
    .get();

  return toPreference(row);
}

/** Distinct users with at least one `digestOnly` preference in this org. */
export async function listDigestSubscribers(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .selectDistinct({ userId: notificationPreferences.userId })
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.digestOnly, true),
      ),
    )
    .all();

  return rows.map((row) => brandId<UserId>(row.userId));
}
